/** Shared markup for the post office and the paused expedition build view. */
import {PATHS,TREE,GOALS,DISCIPLINES,treeRank,treeStatus,treeInvestment,mastery,specializationPoints,growthOn} from './growth.mjs';
const icon=id=>`<svg aria-hidden="true"><use href="#i-${id}"/></svg>`;
export function starChart(p){
 const m=mastery(p),invested=treeInvestment(p),percent=m.next?Math.max(0,Math.min(100,(m.xp-m.start)/(m.next-m.start)*100)):100;
 return `<div class="star-overview"><div class="eyebrow">ZHUYU · THE STAR CHART</div><h3>烛羽的夜航星图 <span>熟练度 ${m.level}</span></h3><p>每一程留下经验，每一次点亮选择方向。</p><div class="mastery-track" role="progressbar" aria-label="信使熟练度" aria-valuenow="${m.xp}" aria-valuemin="${m.start}" aria-valuemax="${m.next||m.xp}"><i style="width:${percent}%"></i></div><small>${m.xp} / ${m.next||'已满级'} 阅历 · 战斗、点灯和送信累计</small></div><p class="panel-lead">邮票点亮星点，顺着连线解锁下一格。每个前置只需 1 级；三条路线可以混搭。<strong>下次启程生效</strong>，公平每日航线使用统一起点。</p><div class="star-paths">${PATHS.map(path=>`<section class="star-path" style="--path-color:${path.color}"><header>${icon(path.icon)}<h3>${path.name}</h3><p>${path.desc}</p></header><ol>${TREE.filter(n=>n.path===path.id).map(n=>{const t=treeStatus(p,n.id),level=treeRank(p,n.id);return `<li class="star-node ${level?'lit':''} ${n.max===1?'keystone':''}"><div class="star-node-top"><h4>${n.name}</h4><span>${level}/${n.max}</span></div><p>${n.desc}</p><button class="small-button" data-action="tree" data-id="${n.id}"${t.allowed?'':' disabled'}>${t.allowed?t.cost+' 邮票 · 点亮':t.reason}</button></li>`;}).join('')}</ol></section>`).join('')}</div><div class="tree-reset"><span>星图已投入 <strong>${invested}</strong> 邮票 · 可免费重配</span><button class="small-button subtle" data-action="reset-tree"${invested?'':' disabled'}>重置星图 · 全额返还</button></div><h3 class="panel-heading">成长目标 <small>${p.growth.claims.length} / ${GOALS.length}</small></h3><div class="growth-goals">${GOALS.map(q=>{const done=p.growth.claims.includes(q.id),value=Math.min(q.goal,q.current(p)),ready=value>=q.goal;return `<article class="goal-card ${done?'claimed':''}"><h4>${q.name}<small>+${q.reward} 邮票</small></h4><p>${q.desc}</p><progress max="${q.goal}" value="${value}" aria-label="${q.name}"></progress><div><small>${Math.floor(value*10)/10} / ${q.goal}</small><button class="small-button" data-action="goal" data-id="${q.id}"${!done&&ready?'':' disabled'}>${done?'已领取':ready?'领取奖励':'继续旅途'}</button></div></article>`;}).join('')}</div>`;
}
export function specializationView(s){
 if(!growthOn(s))return '<p class="panel-lead">本次旅途沿用原有成长规则。新开普通旅途可获得专精点。</p>';
 const points=specializationPoints(s),spent=Object.values(s.growth.disciplines).reduce((a,b)=>a+b,0);
 return `<section class="specialization"><h3 class="panel-heading">本局专精 <small>可用 ${points} 点 · 已用 ${spent}/3</small></h3><p>等级 3 / 5 / 8 各得 1 点，可集中或混搭。加点即时生效，生命上限提升不会回复当前生命。</p><div class="discipline-grid">${DISCIPLINES.map(d=>`<article class="discipline-card">${icon(d.symbol)}<h4>${d.name} <small>${s.growth.disciplines[d.id]}/3</small></h4><p>${d.desc}</p><button class="small-button" data-action="specialize" data-id="${d.id}"${points>0?'':' disabled'}>${points>0?'投入 1 点':'Lv.3 / 5 / 8 获得专精点'}</button></article>`).join('')}</div></section>`;
}
